/** customer-code: customerCode = '<REGION>-<HASH8>', REGION from the postcode,
 * HASH8 = SHA-256(telephone + lastName)[0:8] upper hex. Recomputed exactly from the response. */
@Tag("cp09")
class Cp09Tests extends AcceptanceBase {

	@Test
