		JsonNode r = fetchOwner(createOwnerOk(knownOwner("Sydney"))); // postcode 2000 -> NSW
		String hash8 = shaHex(r.get("telephone").asText() + r.get("lastName").asText(), 8);
		assertEquals("NSW-" + hash8, r.get("customerCode").asText());
	}
}

